','ca930c96-3ef2-4af2-834d-bb73ef04cbaa','caea5aed-3d57-4dda-b590-c6f0f6f8e5f2','cb6983b8-2bc1-4b28-b1d2-aacc4e8e82cc','cd710f14-63ed-4fe8-98ec-ee675cc7557b','ceeaea38-3d26-43ce-af59-92b62f15ca62','cf6b34d7-48a7-4f87-9c39-720004d54fe9','d03a583e-cbbe-409b-9ca7-7d8203e1a234','d304321b-fc00-459c-a950-fca0a516c22e','d55fc0e7-cf87-4961-9cbe-2a1ceeb20d94','d57702c4-d0ab-4eac-986a-900d1448d0db','dadbb5cb-b299-43cb-8b97-378c1c0e5c99','dcaa21b1-6789-4814-a8f0-83790407fb4c','dd883322-8246-402f-9e68-ff5a0f35304c','deb4f068-cf77-41cb-893d-b592bd4ea3b6','df0c9163-2d24-46c4-900c-ba702b578467','e400b815-eb60-4d56-bba8-e577b3daf925','e562572e-9c6c-4f52-b4e7-ca339e6836e1','e609dd41-5ab7-427c-a425-5caef3ae799e','e702c63e-7baf-4727-a0e8-5099500a3118','e91dc46b-bfb8-4e33-a0f2-c549ad4d9c02','eb5fbeee-19d3-4b9a-9893-5c78b2defc58','ec719315-5b10-4387-9d43-841bd4e506e7','ef167404-19ca-4df9-b315-b4cad18251d3','ef64a475-b3e4-46c4-a708-d772d7f475ec','efaa5bfe-7016-4baf-a3e5-324d072c1813','efbc83c9-78bf-4895-98ac-7513de283e2d','f29e0169-e6a3-4aac-9f90-b4f498a77008','f4d0d604-8c7b-4774-b619-aaf4b68ba4e7','f590f042-4f13-4874-bcaa-1d5e2fbf2432','f5cd108b-bf6f-4dfa-991b-5e91e30ced39','f70600a4-a827-4c03-872f-73105933acf3','f863bf3b-4fc4-4728-b403-e4a96f095e13','fb4f8c09-9dfe-49c1-b320-7078f66310e4','fd9d800c-4fb9-4388-ad5f-ee1402383865','fe947d0d-c8e7-4db2-801f-d184dc524340','ff89e5ce-52d6-4f18-abd7-26ec26d26b35','ffcb165f-b106-4a4b-b4d2-2a08e3ad0f9a']::uuid[];
  v_count integer;
  v_amount numeric;
  v_id uuid;
  v_value numeric;
  v_r jsonb;
  v_n integer:=0;
  v_sum numeric:=0;
  v_ids uuid[]:=ARRAY[]::uuid[];
BEGIN
  IF to_regprocedure('public.fn_ca_pay_closed_target_ticket_in_cash(uuid,text)') IS NULL THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_DOOR_MISSING: apply 20261012054804 first';
  END IF;
  SELECT count(*), COALESCE(sum(tk.value),0) INTO v_count,v_amount
    FROM public.tournament_tickets tk WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-17 21:45:00+00' AND tk.created_at<'2026-09-22 08:00:00+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id);
  IF v_count<>190 OR v_amount<>14070.00 THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_PREIMAGE_CHANGED: part 3 has % tickets worth %',v_count,v_amount;
  END IF;
  FOR v_id,v_value IN
    SELECT tk.id,tk.value FROM public.tournament_tickets tk
     WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-17 21:45:00+00' AND tk.created_at<'2026-09-22 08:00:00+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id)
     ORDER BY tk.created_at,tk.id
  LOOP
    v_r:=public.fn_ca_pay_closed_target_ticket_in_cash(v_id,'stranded_ticket_settlement_20261012');
    IF COALESCE((v_r->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE((v_r->>'replayed')::boolean,false)
       OR (v_r->>'amount')::numeric IS DISTINCT FROM v_value THEN
      RAISE EXCEPTION 'STRANDED_TICKET_CASH_REFUSED: %',v_r;
    END IF;
    v_n:=v_n+1;
    v_sum:=round(v_sum+v_value,2);
    v_ids:=v_ids||v_id;
  END LOOP;
  IF v_n<>190 OR v_sum<>14070.00 THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_RESULT_CHANGED: paid % tickets worth %',v_n,v_sum;
  END IF;
  IF (SELECT count(*) FROM public.tournament_tickets tk
       WHERE tk.id=ANY(v_ids) AND tk.status='redeemed'
         AND tk.redeemed_at=transaction_timestamp())<>v_n
     OR (SELECT COALESCE(sum(l.amount),0)
           FROM public.chip_ledger_idem i JOIN public.chip_ledger l ON l.id=i.leg_id
          WHERE i.idempotency_key IN (
            SELECT 'ticket:'||x::text||':closed-target-cash' FROM unnest(v_ids) x)
            AND l.from_type='escrow' AND l.to_type='player_wallet'
            AND l.category='ticket_redeem')<>v_sum
     OR EXISTS (SELECT 1 FROM public.tournament_tickets tk WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-17 21:45:00+00' AND tk.created_at<'2026-09-22 08:00:00+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id)) THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_RESULT_CHANGED: receipts disagree for % tickets worth %',v_n,v_sum;
  END IF;
  RAISE NOTICE 'stranded satellite tickets paid in cash, part 3: % tickets worth %',v_n,v_sum;
END
$settle$;
COMMIT;
